use crate::{
    gestures::{GESTURES, Gestures},
    motion::{Calibration, Motion},
    profiles::ProfileData,
    protocol::{ALL, Fragments, Frame, Recording},
    simulation,
};
use std::io::Cursor;

// Generated by airglove.protocol.serial_line using the original Python simulator.
const PYTHON_FRAME: &str = "AG1 QUcBAAAAAAAAAD8/PA8AAAAA1QMAAAAAAADCAQAAEwEAAAAA1QMAAAAAAADCAQAAEwEAAAAA1QMAAAAAAAC4AaL/EwEAAAAA1QMAAAAAAACbAUn/EwEAAAAA1QMAAAAAAABsAff+EwEAAAAA1QMAAAAAAAAtAbL+EwEqPw==";

#[test]
fn ag1_wire_format_matches_python_and_rejects_bad_crc() {
    let frame = simulation::frame(0, false);
    let mut encoded = Vec::new();
    frame.write(&mut encoded).unwrap();
    assert_eq!(
        std::str::from_utf8(&encoded).unwrap().trim_end(),
        PYTHON_FRAME
    );
    assert_eq!(
        Recording::new(&encoded[..]).unwrap().next_frame().unwrap(),
        Some(frame)
    );
    let mut wire = frame.encode();
    wire[90] ^= 1;
    assert_eq!(Frame::decode(&wire), None);
}

#[test]
fn fragmented_ble_telemetry_survives_mtu_23_and_drops_incomplete_frame() {
    let mut parser = Fragments::default();
    let frame = simulation::frame(100, false);
    let wire = frame.encode();
    let packets: Vec<_> = wire
        .chunks(16)
        .enumerate()
        .map(|(i, part)| {
            let [lo, hi] = frame.sequence.to_le_bytes();
            let mut bytes = vec![0xaf, lo, hi, (i * 16) as u8];
            bytes.extend_from_slice(part);
            bytes
        })
        .collect();
    for (i, packet) in packets.iter().enumerate() {
        if i != 2 {
            assert_eq!(parser.feed(packet), None);
        }
    }
    let decoded: Vec<_> = packets
        .iter()
        .filter_map(|packet| parser.feed(packet))
        .collect();
    assert_eq!(decoded, vec![frame]);
}

#[test]
fn old_logs_keep_timestamps_failure_and_utf16() {
    let log = concat!(
        "23:59:59.950 -> CH0 Palm ACC=(0,0,981) GYR=(0,0,0) MAG=(450,0,275)\r\n",
        "23:59:59.950 -> CH4 Ring FAIL I2C read\r\n",
        "00:00:00.030 -> CH0 Palm ACC=(0,0,981) GYR=(0,0,0) MAG=(450,0,275)\r\n",
    );
    let mut utf16 = vec![0xff, 0xfe];
    utf16.extend(log.encode_utf16().flat_map(u16::to_le_bytes));
    let mut recording = Recording::new(Cursor::new(utf16)).unwrap();
    let first = recording.next_frame().unwrap().unwrap();
    let second = recording.next_frame().unwrap().unwrap();
    assert_eq!(first.valid(), 1);
    assert!(first.samples[4].is_none());
    assert_eq!(second.millis - first.millis, 80);
    assert!(recording.next_frame().unwrap().is_none());
}

#[test]
fn demo_reproduces_desktop_gestures_and_requires_recalibration_after_loss() {
    let mut motion = Motion::default();
    motion.calibrate();
    let mut moved = false;
    let mut scroll = [false; 2];
    let mut click = [false; 2];
    for index in 0..1250 {
        let frame = simulation::frame(index, false);
        let action = motion.feed(frame, 1.);
        if frame.valid() != ALL {
            assert!(!motion.ready());
            assert!(action.click.is_none() && action.wheel == 0 && action.dx == 0.);
        }
        moved |= action.dx.abs() + action.dy.abs() > 2.;
        if action.wheel != 0 {
            scroll[usize::from(action.wheel > 0)] = true;
        }
        if let Some(right) = action.click {
            click[usize::from(right)] = true;
        }
    }
    assert!(moved, "cursor movement");
    assert_eq!(scroll, [true; 2]);
    assert_eq!(click, [true; 2]);
    assert!(!motion.ready());
}

#[test]
fn large_gap_requires_recalibration() {
    let mut motion = Motion::default();
    motion.calibrate();
    for index in 0..70 {
        motion.feed(simulation::frame(index, false), 1.);
    }
    assert!(motion.ready());
    motion.feed(simulation::frame(99, false), 1.);
    assert!(motion.calibration == Calibration::Idle);
    assert!(!motion.ready());
}

#[test]
fn practice_reproduces_each_key_and_one_snap() {
    let invoker = &ProfileData::default().profiles[1];
    let mut motion = Motion::default();
    let mut gestures = Gestures::default();
    motion.calibrate();
    let mut keys = Vec::new();
    let mut snaps = 0;
    for index in 0..simulation::PRACTICE_FRAMES {
        let frame = simulation::frame(index, true);
        motion.feed(frame, 1.);
        if let Some(gesture) = gestures.feed(frame.millis, &motion, None) {
            if gesture == 6 {
                snaps += 1;
            } else {
                keys.push(invoker.binding(GESTURES[gesture].0).key);
            }
        }
    }
    assert_eq!(keys, simulation::KEYS);
    assert_eq!(snaps, 1);
}

#[test]
fn cli_preserves_existing_sources_and_rejects_conflicting_options() {
    assert!(
        matches!(crate::parse(["--port","COM5"].map(Into::into)), Ok(crate::Source::Usb(port)) if port == "COM5")
    );
    assert!(matches!(
        crate::parse(["--ble", "--address", "AA:BB:CC:DD:EE:FF"].map(Into::into)),
        Ok(crate::Source::Bluetooth(_))
    ));
    assert!(crate::parse(["--ble", "--usb"].map(Into::into)).is_err());
    assert!(crate::parse(["--usb", "--address", "AA:BB:CC:DD:EE:FF"].map(Into::into)).is_err());
}
